  /* ---------- THE BESTIARY ---------- */
  bestiarium: [
    { name: "Bugbear", bild: "bugbear.jpg", status: "besiegt", ort: "The watchtower", text: "A huge, hairy goblin warrior with yellowish fur and long, sharp claws. Guarded the prisoners in the watchtower, dealt Echo a deep wound and finally fell to Friedrich's sword and Ezekiel's daggers." },
    { name: "Venomfang", bild: "venomfang.jpg", status: "besiegt", ort: "The watchtower of Thundertree", text: "A kind of young green poison dragon. This one had made its lair in the crumbling watchtower. Its poison breath dealt the party a nasty blow until Barradin's hypnosis turned the tide." },
    { name: "Blight", bild: "blight.jpg", status: "besiegt", ort: "The abandoned village of Thundertree", text: "Small, gnarled creatures of roots and twisted wood with ruby-red eyes. Quicker than expected and fond of ambushes, but Echo's fireball turned the last of them to ash." },
    { name: "Chasme", bild: "chasme.jpg", status: "besiegt", ort: "The prison in the Underdark", text: "A huge, wasp-like demon with a long sucking stinger and a deafening buzz. Struck Friedrich down with a single sting, until Ezekiel rammed his dagger into its eye." },
    { name: "Vrock", bild: "vrock.jpg", status: "besiegt", ort: "The prison in the Underdark", text: "A vulture-like demon with ragged wings. Rampaged among the guards in the courtyard of Ilvara's fortress until Echo burned out the last of its life force with a blinding bolt of lightning." },
    { name: "Kuo-Toa Cultists", bild: "kuo-toa.jpg", status: "gefallen", ort: "The city by the underground lake", text: "Not all kuo-toa were our enemies – Archpriest Ploopploopeen and his faithful stood on our side. We fought the followers of the false archpriestess, who worshipped Demogorgon as a god. In the city centre they turned on their own people and on the companions. When their demon god really came, he dragged the whole city down with him – friend and foe alike." },
    { name: "Demogorgon", bild: "demogorgon-karte.webp", status: "gesichtet", ort: "The underground lake", text: "A demon prince with two heads, tentacle arms and a long tail. His scream snuffed out all magic, and the companions escaped only by luck. Friedrich punched him anyway. Or so he says." }
  ],

